// Verify the HMAC forwarded by the Next.js Stripe webhook (same pattern as the
// concierge workflow) and normalize the subscriber payload.
const crypto = require('crypto');
const secret = $env.N8N_SHARED_SECRET;
const raw = JSON.stringify($json.body);
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
const got = $json.headers['x-ostentaculus-signature'] || '';
const a = Buffer.from(expected); const b = Buffer.from(got);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) { throw new Error('Invalid ingress signature'); }

const p = $json.body;
// Only act on the ProÊxito B2C trial product; ignore anything else.
if (p.product !== 'proexito_trial') return [];
const phone = String(p.phone || '').replace(/\D/g, '');
if (!phone) throw new Error('Subscriber phone missing — enable phone_number_collection or resolve the lead first');
const lang = (p.lang === 'es') ? 'es' : 'pt';
const goal = ['sono', 'ansiedade', 'foco'].includes(p.goal) ? p.goal : 'bem-estar';
const firstName = String(p.name || '').trim().split(' ')[0] || (lang === 'es' ? 'hola' : 'olá');
// Template + video header URL per language (approved in Meta Business Manager).
const template = lang === 'es' ? 'proexito_bienvenida' : 'proexito_boasvindas';
const langCode = lang === 'es' ? 'es_ES' : 'pt_BR';
const videoUrl = lang === 'es' ? $env.PX_WELCOME_VIDEO_URL_ES : $env.PX_WELCOME_VIDEO_URL_PT;
return [{ json: { phone, lang, goal, firstName, template, langCode, videoUrl, email: p.email || null } }];
